<?php

namespace App\Services\Store;

use App\Models\Booking;
use App\Models\Product;
use Carbon\CarbonImmutable;

/**
 * Step CG-4.5 — which booking slots a buyer may pick, and whether a slot they picked is still free.
 *
 * The product's `availability` setting is a weekly pattern in the **brand's** timezone (weekdays,
 * a start and end time, slot length, a buffer between slots, how much notice is needed and how far
 * ahead the calendar runs). Slots are generated by local wall time and then converted, the same way
 * a post's `scheduled_at_utc` is computed from its account's local time, so "10:00" stays 10:00 for
 * the creator either side of a clocks change.
 *
 * Two DST details fall out of that and are deliberate:
 *
 *  - a local time that doesn't exist on a spring-forward day is **dropped** (it would silently slide
 *    into the next hour), detected by round-tripping the instant back to local time;
 *  - on a fall-back day the earlier of the two identical local times wins, and the slot is stored as
 *    one instant, so a buyer and the creator always mean the same moment.
 */
class BookingSlotService
{
    /**
     * @return array{weekdays: list<int>, start: string, end: string, slot_minutes: int, buffer_minutes: int, lead_hours: int, days_ahead: int}
     */
    public function availability(Product $product): array
    {
        /** @var array<string, mixed> $set */
        $set = $product->setting('availability', []);

        /** @var list<int> $weekdays */
        $weekdays = array_values(array_filter(
            array_map('intval', (array) ($set['weekdays'] ?? [1, 2, 3, 4, 5])),
            fn (int $day) => $day >= 1 && $day <= 7,
        ));

        return [
            'weekdays' => $weekdays === [] ? [1, 2, 3, 4, 5] : $weekdays,
            'start' => $this->time($set['start'] ?? null, '09:00'),
            'end' => $this->time($set['end'] ?? null, '17:00'),
            'slot_minutes' => max(5, (int) ($set['slot_minutes'] ?? config('payments.bookings.slot_minutes', 30))),
            'buffer_minutes' => max(0, (int) ($set['buffer_minutes'] ?? config('payments.bookings.buffer_minutes', 0))),
            'lead_hours' => max(0, (int) ($set['lead_hours'] ?? config('payments.bookings.lead_hours', 24))),
            'days_ahead' => max(1, min((int) ($set['days_ahead'] ?? config('payments.bookings.days_ahead', 30)), 120)),
        ];
    }

    /**
     * The bookable slots, soonest first, with a label already in the brand's timezone so no caller
     * (or page) has to know what that timezone is.
     *
     * @return list<array{starts_at: string, ends_at: string, label: string}>
     */
    public function slots(Product $product, ?CarbonImmutable $now = null): array
    {
        $availability = $this->availability($product);
        $timezone = $this->timezone($product);
        $now = ($now ?? CarbonImmutable::now())->utc();
        $earliest = $now->addHours($availability['lead_hours']);
        $taken = $this->takenInstants($product);

        $slots = [];
        $day = $now->setTimezone($timezone)->startOfDay();

        for ($offset = 0; $offset <= $availability['days_ahead']; $offset++) {
            $date = $day->addDays($offset);

            if (! in_array($date->dayOfWeekIso, $availability['weekdays'], true)) {
                continue;
            }

            foreach ($this->localTimes($availability) as $time) {
                $startsAt = $this->toUtc($date->toDateString(), $time, $timezone);

                if ($startsAt === null || $startsAt->isBefore($earliest) || in_array($startsAt->toIso8601String(), $taken, true)) {
                    continue;
                }

                $endsAt = $startsAt->addMinutes($availability['slot_minutes']);

                $slots[] = [
                    'starts_at' => $startsAt->toIso8601String(),
                    'ends_at' => $endsAt->toIso8601String(),
                    'label' => $startsAt->setTimezone($timezone)->isoFormat('ddd D MMM · HH:mm'),
                ];
            }
        }

        return $slots;
    }

    /**
     * Is this exact instant one of the product's offered, un-taken slots? Checked again at checkout,
     * because the list the buyer saw may be minutes old.
     */
    public function isBookable(Product $product, CarbonImmutable $startsAt, ?CarbonImmutable $now = null): bool
    {
        $wanted = $startsAt->utc()->toIso8601String();

        foreach ($this->slots($product, $now) as $slot) {
            if ($slot['starts_at'] === $wanted) {
                return true;
            }
        }

        return false;
    }

    public function timezone(Product $product): string
    {
        $timezone = $product->client->organization->default_timezone ?? config('app.timezone', 'UTC');

        return in_array($timezone, timezone_identifiers_list(), true) ? $timezone : 'UTC';
    }

    /**
     * Local "HH:MM" start times across one day's window, stepping by slot + buffer.
     *
     * @param  array{start: string, end: string, slot_minutes: int, buffer_minutes: int}  $availability
     * @return list<string>
     */
    private function localTimes(array $availability): array
    {
        $step = $availability['slot_minutes'] + $availability['buffer_minutes'];
        $start = $this->minutes($availability['start']);
        $end = $this->minutes($availability['end']);
        $times = [];

        for ($minute = $start; $minute + $availability['slot_minutes'] <= $end; $minute += $step) {
            $times[] = sprintf('%02d:%02d', intdiv($minute, 60), $minute % 60);
        }

        return $times;
    }

    /**
     * The UTC instant for a local date + time, or null when that local time doesn't exist on that
     * date (the hour a spring-forward skips).
     */
    private function toUtc(string $date, string $time, string $timezone): ?CarbonImmutable
    {
        $local = CarbonImmutable::parse($date.' '.$time.':00', $timezone);

        return $local->format('H:i') === $time ? $local->utc() : null;
    }

    /**
     * @return list<string>
     */
    private function takenInstants(Product $product): array
    {
        return array_values(Booking::query()
            ->where('product_id', $product->id)
            ->where('status', 'booked')
            ->pluck('starts_at')
            ->map(fn ($instant) => CarbonImmutable::parse($instant)->utc()->toIso8601String())
            ->all());
    }

    private function minutes(string $time): int
    {
        [$hour, $minute] = array_pad(explode(':', $time), 2, '0');

        return ((int) $hour) * 60 + (int) $minute;
    }

    private function time(mixed $value, string $fallback): string
    {
        return is_string($value) && preg_match('/^([01]\d|2[0-3]):[0-5]\d$/', $value) === 1 ? $value : $fallback;
    }
}
